import { Container, Spacer, Text } from "@mariozechner/pi-tui";
import { theme } from "../theme/theme.js";
import { DynamicBorder } from "./dynamic-border.js";

interface UserMessageItem {
	index: number; // Index in the full messages array
	text: string; // The message text
	timestamp?: string; // Optional timestamp if available
}

/**
 * Component that renders a user message selector for branching
 */
export class UserMessageSelectorComponent extends Container {
	private listContainer: Container;
	private messages: UserMessageItem[] = [];
	private selectedIndex: number = 0;
	private maxVisible: number = 10;
	private onSelectCallback: (messageIndex: number) => void;
	private onCancelCallback: () => void;

	constructor(messages: UserMessageItem[], onSelect: (messageIndex: number) => void, onCancel: () => void) {
		super();

		this.messages = messages;
		this.onSelectCallback = onSelect;
		this.onCancelCallback = onCancel;

		// Start with the last (most recent) message selected
		this.selectedIndex = Math.max(0, messages.length - 1);

		// Add top border
		this.addChild(new DynamicBorder());
		this.addChild(new Spacer(1));

		// Add title and description
		this.addChild(new Text(theme.bold("Branch from Message"), 0, 0));
		this.addChild(new Text(theme.fg("muted", "Select a message to create a new branch from that point"), 0, 0));
		this.addChild(new Spacer(1));

		// Create list container
		this.listContainer = new Container();
		this.addChild(this.listContainer);

		this.addChild(new Spacer(1));

		// Add bottom border
		this.addChild(new DynamicBorder());

		// Initial render
		this.updateList();

		// Auto-cancel if no messages or only one message
		if (messages.length <= 1) {
			setTimeout(() => onCancel(), 100);
		}
	}

	private updateList(): void {
		this.listContainer.clear();

		if (this.messages.length === 0) {
			this.listContainer.addChild(new Text(theme.fg("muted", "  No user messages found"), 0, 0));
			return;
		}

		// Calculate visible range with scrolling
		const startIndex = Math.max(
			0,
			Math.min(this.selectedIndex - Math.floor(this.maxVisible / 2), this.messages.length - this.maxVisible),
		);
		const endIndex = Math.min(startIndex + this.maxVisible, this.messages.length);

		// Render visible messages (2 lines per message + blank line)
		for (let i = startIndex; i < endIndex; i++) {
			const message = this.messages[i];
			if (!message) continue;

			const isSelected = i === this.selectedIndex;

			// Normalize message to single line
			const normalizedMessage = message.text.replace(/\n/g, " ").trim();

			// First line: cursor + message
			let messageLine = "";
			if (isSelected) {
				const prefix = theme.fg("accent", "→ ");
				messageLine = prefix + theme.bold(theme.fg("accent", normalizedMessage));
			} else {
				messageLine = `  ${normalizedMessage}`;
			}

			this.listContainer.addChild(new Text(messageLine, 0, 0));

			// Second line: metadata (position in history)
			const position = i + 1;
			const metadata = theme.fg("muted", `  Message ${position} of ${this.messages.length}`);
			this.listContainer.addChild(new Text(metadata, 0, 0));
			this.listContainer.addChild(new Spacer(1)); // Blank line between messages
		}

		// Add scroll indicator if needed
		if (startIndex > 0 || endIndex < this.messages.length) {
			const scrollInfo = theme.fg("muted", `  (${this.selectedIndex + 1}/${this.messages.length})`);
			this.listContainer.addChild(new Text(scrollInfo, 0, 0));
		}
	}

	handleInput(keyData: string): void {
		// Up arrow - go to previous (older) message
		if (keyData === "\x1b[A") {
			this.selectedIndex = Math.max(0, this.selectedIndex - 1);
			this.updateList();
		}
		// Down arrow - go to next (newer) message
		else if (keyData === "\x1b[B") {
			this.selectedIndex = Math.min(this.messages.length - 1, this.selectedIndex + 1);
			this.updateList();
		}
		// Enter - select message and branch
		else if (keyData === "\r") {
			const selected = this.messages[this.selectedIndex];
			if (selected) {
				this.onSelectCallback(selected.index);
			}
		}
		// Escape - cancel
		else if (keyData === "\x1b") {
			this.onCancelCallback();
		}
	}
}

